import {
  S3Client,
  GetObjectCommand,
  PutObjectCommand,
} from "@aws-sdk/client-s3";
import {
  DynamoDBClient,
  GetItemCommand,
  PutItemCommand,
} from "@aws-sdk/client-dynamodb";
import {
  CloudFrontClient,
  CreateInvalidationCommand,
} from "@aws-sdk/client-cloudfront";
import {
  validateTenantAccess,
  getTenantIdFromRequest,
  extractRolesFromEvent,
  assertHttpsUrls,
  createResponse,
} from "admin-auth";
import { createLogger, logRequest } from 'admin-auth';

const logger = createLogger('brandings');

const s3ISP = new S3Client({ region: process.env.AWS_REGION });
const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });
const cloudFront = new CloudFrontClient({ region: process.env.AWS_REGION });

/**
 * Construct the shared SP Portal bucket name from environment variables.
 */
function getSharedSpPortalBucket() {
  const prefix = process.env.SPPORTAL_BUCKET_PREFIX || "";
  const accountId = prefix.split("-")[0] || "";
  const region = process.env.AWS_REGION || "us-east-1";
  return `sp-portal-shared-${accountId}-${region}`;
}

/**
 * Get AMFA branding from DynamoDB
 */
async function getAmfaBranding(tenantId) {
  const configTable = process.env.AMFACONFIG_TABLE;
  if (!configTable) throw new Error("AMFACONFIG_TABLE not set");

  const result = await dynamodb.send(new GetItemCommand({
    TableName: configTable,
    Key: {
      id: { S: tenantId },
      configtype: { S: 'amfaBrandings' },
    },
  }));

  if (result.Item?.value?.S) {
    return JSON.parse(result.Item.value.S);
  }
  return null;
}

/**
 * Put AMFA branding to DynamoDB
 */
async function putAmfaBranding(tenantId, data) {
  const configTable = process.env.AMFACONFIG_TABLE;
  if (!configTable) throw new Error("AMFACONFIG_TABLE not set");

  await dynamodb.send(new PutItemCommand({
    TableName: configTable,
    Item: {
      id: { S: tenantId },
      configtype: { S: 'amfaBrandings' },
      value: { S: JSON.stringify(data) },
    },
  }));

  return data;
}

/**
 * Get AMFA legal URLs from DynamoDB (amfaLegals)
 */
async function getAmfaLegals(tenantId) {
  const configTable = process.env.AMFACONFIG_TABLE;
  if (!configTable) throw new Error("AMFACONFIG_TABLE not set");

  const result = await dynamodb.send(new GetItemCommand({
    TableName: configTable,
    Key: {
      id: { S: tenantId },
      configtype: { S: 'amfaLegals' },
    },
  }));

  if (result.Item?.value?.S) {
    return JSON.parse(result.Item.value.S);
  }
  return null;
}

/**
 * Put AMFA legal URLs to DynamoDB (amfaLegals)
 */
async function putAmfaLegals(tenantId, data) {
  const configTable = process.env.AMFACONFIG_TABLE;
  if (!configTable) throw new Error("AMFACONFIG_TABLE not set");

  await dynamodb.send(new PutItemCommand({
    TableName: configTable,
    Item: {
      id: { S: tenantId },
      configtype: { S: 'amfaLegals' },
      value: { S: JSON.stringify(data) },
    },
  }));

  return data;
}

// Legal fields that are stored in amfaLegals but exposed via _amfa branding API
const LEGAL_FIELDS = ['terms_of_service', 'privacy_policy'];

// URL-typed branding fields; stored values must be https: (amfa-442 #9).
// Login Service (_amfa) fields edited by LoginServiceBrandingEdit.jsx.
const AMFA_URL_FIELDS = ['logo_url', 'email_logo_url', 'favicon_url', ...LEGAL_FIELDS];
// SP Portal / Admin Portal (S3 branding.json) fields edited by BrandingList.jsx.
const PORTAL_URL_FIELDS = ['app_login_logo_url', 'fav_icon_url', 'app_bar_logo_url', 'app_terms_url', 'app_privacy_url'];

// Server-side allowlist of the keys the two branding forms edit (D10). Stored
// values reach end-user emails and portals, so anything else is a 400 naming
// the key. 'meta' keys are the ones the GET response itself adds and the form
// sends back; they are passed through untouched.
const TEXT_MAX = { name: 100, desc: 500 };
const URL_MAX = 2048;
const COLOR_RE = /^#[0-9A-Fa-f]{6}$/;
const META_KEYS = ['id', 'name', 'url', 'tenant_id', 'portal_type', 'tenant_name'];
const AMFA_FIELD_TYPES = {
  service_name: 'name', mobile_token_svc_name: 'name',
  brand_base_color: 'color', login_page_bg_color: 'color', login_page_border_color: 'color', login_page_controller_bg_color: 'color',
  ...Object.fromEntries(AMFA_URL_FIELDS.map((f) => [f, 'url'])),
};
const PORTAL_FIELD_TYPES = {
  name: 'name', app_title_msg: 'name', portal_title_msg: 'name', portal_description_msg: 'desc',
  login_page_center_color: 'color', login_page_outter_color: 'color', app_bar_start_color: 'color', app_bar_end_color: 'color', app_title_icon_color: 'color',
  ...Object.fromEntries(PORTAL_URL_FIELDS.map((f) => [f, 'url'])),
};

const validationError = (message) => {
  const error = new Error(message);
  error.statusCode = 400;
  error.expose = true;
  error.type = 'validation_error';
  return error;
};

/** Reject unknown keys and out-of-bounds values; empty strings mean "unset" and pass. */
function assertBrandingFields(data, fieldTypes) {
  if (data === null || typeof data !== 'object' || Array.isArray(data)) throw validationError('data: must be an object');
  for (const [key, value] of Object.entries(data)) {
    const type = fieldTypes[key];
    if (!type) {
      if (META_KEYS.includes(key)) continue;
      throw validationError(`${key}: unknown branding field`);
    }
    if (value === undefined || value === null || value === '') continue;
    if (typeof value !== 'string') throw validationError(`${key}: must be a string`);
    if (type === 'color' && !COLOR_RE.test(value)) throw validationError(`${key}: must be a #RRGGBB colour`);
    const max = type === 'url' ? URL_MAX : TEXT_MAX[type];
    if (type !== 'color' && value.length > max) throw validationError(`${key}: must be at most ${max} characters`);
  }
}

export const handler = async (event) => {
  logRequest(logger, event);
  logger.info("event.requestContext.http.method:", event.requestContext.http.method);

  const portalType = event.pathParameters?.id;

  // Check if this is an AMFA Service branding request (id ends with _amfa)
  const isAmfaBranding = portalType?.endsWith('_amfa');
  const isSpPortalBranding = portalType?.endsWith('_spportal');

  if (isAmfaBranding) {
    // ===== AMFA Service branding (DynamoDB) =====
    const tenantId = portalType.replace(/_amfa$/, '');

    // Validate tenant access
    const authResult = await validateTenantAccess(event, tenantId);
    if (!authResult.authorized) {
      return createResponse(authResult.statusCode, { error: authResult.error });
    }

    logger.info(`AMFA branding request for tenant: ${tenantId}`);

    try {
      switch (event.requestContext.http.method) {
        case "GET":
          // Fetch both amfaBrandings and amfaLegals in parallel
          const [amfaData, legalsData] = await Promise.all([
            getAmfaBranding(tenantId),
            getAmfaLegals(tenantId),
          ]);
          return createResponse(200, {
            data: {
              id: portalType,
              portal_type: 'Login Service Portal',
              tenant_id: tenantId,
              tenant_name: amfaData?.service_name || tenantId,
              name: amfaData?.service_name || tenantId,
              ...(amfaData || {}),
              ...(legalsData || {}),
            },
          });
        case "PUT":
          const payload = JSON.parse(event.body);
          const putData = payload.data;
          assertBrandingFields(putData, AMFA_FIELD_TYPES);
          assertHttpsUrls(putData, AMFA_URL_FIELDS);
          // Remove non-branding fields before saving
          const { id, portal_type, tenant_id, tenant_name, name, ...allFields } = putData;
          // Split legal fields from branding fields
          const legalData = {};
          const brandingData = {};
          for (const [key, val] of Object.entries(allFields)) {
            if (LEGAL_FIELDS.includes(key)) {
              legalData[key] = val;
            } else {
              brandingData[key] = val;
            }
          }
          // Save both in parallel (merge with existing legals to preserve other fields)
          const existingLegals = await getAmfaLegals(tenantId);
          await Promise.all([
            putAmfaBranding(tenantId, brandingData),
            putAmfaLegals(tenantId, { ...(existingLegals || {}), ...legalData }),
          ]);
          return createResponse(200, { data: { id: portalType, ...brandingData, ...legalData } });
        case "OPTIONS":
          return createResponse(200, { data: "ok" });
        default:
          return createResponse(404, { data: "Not Found" });
      }
    } catch (e) {
      logger.info("AMFA branding error:", e);
      if (e.expose && e.statusCode) {
        return createResponse(e.statusCode, { type: e.type || "exception", message: e.message });
      }
      return createResponse(500, { type: "exception", message: e.message || "Service Error" });
    }
  }

  // ===== SP Portal / Admin Portal branding (S3) =====
  const spPortalBucket = getSharedSpPortalBucket();
  let s3Key;
  let tenantId = null;

  if (isSpPortalBranding) {
    // Tenant SP Portal branding: /brandings/{tenantId}_spportal
    tenantId = portalType.replace(/_spportal$/, '');
    s3Key = `branding_${tenantId}.json`;

    const authResult = await validateTenantAccess(event, tenantId);
    if (!authResult.authorized) {
      return createResponse(authResult.statusCode, { error: authResult.error });
    }
  } else if (portalType === "adminportal") {
    // Admin portal branding: branding.json is platform-wide, SA only (amfa-442 #8)
    if (!extractRolesFromEvent(event).includes("SA")) {
      return createResponse(403, { error: "Only SA can access admin portal branding" });
    }
    s3Key = "branding.json";
  } else {
    // Legacy: portalType is a tenantId directly (e.g., /brandings/testtenantb)
    tenantId = portalType;
    s3Key = `branding_${tenantId}.json`;

    // If a tenant_id header is provided, use that instead
    const headerTenantId = getTenantIdFromRequest(event);
    if (headerTenantId) {
      tenantId = headerTenantId;
      s3Key = `branding_${tenantId}.json`;
    }

    if (tenantId && tenantId !== 'adminportal') {
      const authResult = await validateTenantAccess(event, tenantId);
      if (!authResult.authorized) {
        return createResponse(authResult.statusCode, { error: authResult.error });
      }
    }
  }

  logger.info(`SP Portal branding request: bucket=${spPortalBucket}, key=${s3Key}, tenantId=${tenantId}`);

  const getResData = async () => {
    const params = { Bucket: spPortalBucket, Key: s3Key };
    logger.info(`Getting branding from s3://${spPortalBucket}/${s3Key}`);
    const data = await s3ISP.send(new GetObjectCommand(params));
    const body = await data.Body.transformToString();
    return JSON.parse(body);
  };

  const putResData = async (data) => {
    const params = {
      Bucket: spPortalBucket,
      Key: s3Key,
      Body: JSON.stringify(data, null, 2),
      ContentType: "application/json",
    };
    logger.info(`Putting branding to s3://${spPortalBucket}/${s3Key}`);
    await s3ISP.send(new PutObjectCommand(params));

    const distributionId =
      process.env.SPPORTAL_DISTRIBUTION_ID ||
      process.env.ADMINPORTAL_DISTRIBUTION_ID;
    if (distributionId) {
      try {
        await cloudFront.send(
          new CreateInvalidationCommand({
            DistributionId: distributionId,
            InvalidationBatch: {
              CallerReference: Date.now().toString(),
              Paths: { Quantity: 1, Items: [`/${s3Key}`] },
            },
          }),
        );
      } catch (cfError) {
        logger.warn("CloudFront invalidation failed (non-fatal):", cfError.message);
      }
    }

    return data;
  };

  try {
    switch (event.requestContext.http.method) {
      case "GET":
        const getResult = await getResData();
        return createResponse(200, {
          data: {
            ...getResult,
            id: portalType, // must be AFTER spread to prevent overwrite by S3 data
            url: process.env.SP_PORTAL_URL,
            tenant_id: tenantId,
          },
        });
      case "PUT":
        const payload = JSON.parse(event.body);
        assertBrandingFields(payload.data, PORTAL_FIELD_TYPES);
        assertHttpsUrls(payload.data, PORTAL_URL_FIELDS);
        const putResult = await putResData(payload.data);
        return createResponse(200, { data: putResult });
      case "OPTIONS":
        return createResponse(200, { data: "ok" });
      default:
        return createResponse(404, { data: "Not Found" });
    }
  } catch (e) {
    logger.info("Catch an error:", e);
    if (e.expose && e.statusCode) {
      return createResponse(e.statusCode, { type: e.type || "exception", message: e.message });
    }
    return createResponse(500, { type: "exception", message: e.message || "Service Error" });
  }
};
